#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Cmyk { pub c: f32, pub m: f32, pub y: f32, pub k: f32 }

#[inline]
fn max2(a: f32, b: f32) -> f32 { if a < b { b } else { a } }

pub fn rgb_to_cmyk(r: f32, g: f32, b: f32) -> Cmyk {
    let max = max2(max2(r, g), b);
    let k = 1.0f32 - max;
    if k == 1.0f32 {
        Cmyk { c: 0.0f32, m: 0.0f32, y: 0.0f32, k }
    } else {
        let den = 1.0f32 - k;
        Cmyk {
            c: (1.0f32 - r - k) / den,
            m: (1.0f32 - g - k) / den,
            y: (1.0f32 - b - k) / den,
            k,
        }
    }
}

fn main() {
    use std::io::{self, Read, Write};
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let out = io::stdout();
